def solve(inputs: dict) -> float:
    n = inputs["n"]
    k = inputs["k"]

    # Simulate the Josephus problem
    people = list(range(1, n + 1))
    idx = 0

    while len(people) > 1:
        # Remove every k-th person
        idx = (idx + k - 1) % len(people)
        people.pop(idx)
        # After removal, idx points to the next person in the circular list
        if len(people) > 0:
            idx = idx % len(people)

    return float(people[0])
